eval:
(()=>{const o={today:APP.today()};const s=APP.ASSIST.cur();const cl=(x,n)=>String(x==null?'':x).slice(0,n||200);
o.user=(s.msgs||[]).filter(m=>m.role==='user').map((m,i)=>(i+1)+'['+APP.ASSIST.msgId(m)+'] '+cl(m.text,110)+((m.corr||[]).length?' {corr:'+JSON.stringify(m.corr).slice(0,200)+'}':'')+(m.textHist?' {hist:'+JSON.stringify(m.textHist).slice(0,200)+'}':''));
o.sys=(s.msgs||[]).filter(m=>m.role!=='user').slice(-4).map(m=>m.role+': '+cl(m.text,260));
o.probs=APP.liveAll().map(r=>{const pg=APP.S.get('eprog_'+r.p.id)||{};const sv=pg.solve||{};const L=sv.live||{};return {t:cl(r.p.title,50),st:APP.liveClosure(r.p.id).state,stmt:cl(r.p.statement,220),psrc:cl(JSON.stringify(r.p.src||null),160),pfix:cl(JSON.stringify(r.p.fixHist||null),300),u1:cl(JSON.stringify(sv.u||null),400),g:cl(JSON.stringify(sv.g||null),500),chat:cl(JSON.stringify(L.chat||null),300),chk:cl(JSON.stringify(L.check||L.chk||sv.chk||null),300),plan:cl(JSON.stringify(L.plan||null),160),retr:cl(JSON.stringify(L.retracts||null),500),steps:(L.steps||[]).map(x=>cl((x.text||''),50)+' due='+x.due+' out='+cl(JSON.stringify(x.out||null),300)+' fix='+cl(JSON.stringify(x.fixHist||null),200)),bk:cl(JSON.stringify(L.back||sv.b||null),400)}});
o.plans=(APP.ASSIST.plansAll?APP.ASSIST.plansAll(s):[]).map(x=>{const p=x.p;return p.id+' «'+cl(p.text,60)+'» when='+p.when+' state='+p.state+(p.corr?' corr='+cl(JSON.stringify(p.corr),200):'')});
o.guesses=((s.coach||{}).guesses||[]).map(g=>g.id+' «'+cl(g.text,60)+'» res='+(g.res||'')+(g.resWhy?' why='+cl(g.resWhy,80):'')+(g.wd||g.retracted?' WD':'')+(g.corr?' corr='+cl(JSON.stringify(g.corr),200):''));
o.retracts=cl(JSON.stringify((s.coach||{}).retracts||null),700)+' | se='+cl(JSON.stringify(s.retracts||null),700);
try{o.asks=((APP.S.get(s.id)||s).copyAsk||[]).map(q=>q.state+' '+q.label+': «'+cl(q.old,60)+'» ⇒ «'+cl(q.new,60)+'»');}catch(e){o.asks='ERR '+e.message}
try{const P=APP.MIND.phases();o.mind=(P.weakest?'WEAK '+P.weakest.fa+' ':'nodistinct ')+P.rows.map(X=>X.fa+' '+X.k+'/'+X.n+' acts:'+(X.acts||[]).map(a=>(a.ok?'+':'-')+a.src+(a.wd||a.withdrawn?'(wd)':'')).join(',')).join(' || ');}catch(e){o.mind='ERR '+e.message}
try{o.prc=(APP.PR?APP.PR.cases():[]).map(c=>c.id+' T'+c.tid+' '+c.state+' due='+c.due+' sess='+(c.sessions||[]).map(x=>x.d+(x.ok===false?'✗':x.ok===true?'✓':'')+(x.meas&&x.meas.pct!=null?'('+x.meas.pct+'%)':'')+(x.src?'['+x.src+']':'')).join(',')+' stable='+cl(JSON.stringify(c.stable||null),120)+' off='+cl(JSON.stringify(c.stableOff||null),120));}catch(e){o.prc='ERR '+e.message}
try{const d=APP.dossier(APP.liveAll().slice(-1)[0].p.id);o.dossier=(d.events||[]).length+' events: '+(d.events||[]).map(e=>e.k+(e.hist&&e.hist.length?'*':'')).join(',');}catch(e){o.dossier='ERR '+e.message}
return JSON.stringify(o,null,1);})()
